describe("course-support closeout playbook decision basis", () => {
  it("reports a canonical joint next-stage and attempt histogram", () => {
    const result = buildCourseSupportCloseoutPlaybookDecisionBasis({
      incidents: [
        {
          cycle: 1,
          attemptLedger: browserAdapterRetryFailedRetryableAttemptLedger(1, 2),
        },
        { cycle: 1, attemptLedger: { version: 1, events: [] } },
        { cycle: 1, attemptLedger: typedAdapterReadyAttemptLedger() },
        { cycle: 1, attemptLedger: typedAdapterReadyAttemptLedger() },
      ],
    });

    expect(result).toEqual({
      playbookAssessmentAvailableIncidentCount: 4,
      playbookAssessmentInvalidIncidentCount: 0,
      playbookExhaustedCount: 0,
      incompletePlaybookCount: 4,
      zeroAttemptBrowserAdapterRetryCount: 0,
      incompletePlaybookNextStageAttemptHistogram: [
        {
          nextStage: "OFFICIAL_IDENTITY",
          attemptCount: 0,
          incidentCount: 1,
        },
        {
          nextStage: "TYPED_ADAPTER",
          attemptCount: 0,
          incidentCount: 2,
        },
        {
          nextStage: "BROWSER_ADAPTER_RETRY",
          attemptCount: 2,
          incidentCount: 1,
        },
      ],
    });
    expect(
      result.incompletePlaybookNextStageAttemptHistogram?.reduce(
        (total, entry) => total + entry.incidentCount,
        0,
      ),
    ).toBe(result.incompletePlaybookCount);
  });

  it("keeps a proven zero Browser Adapter retry and complete playbook distinct", () => {
    const result = buildCourseSupportCloseoutPlaybookDecisionBasis({
      incidents: [
        { cycle: 1, attemptLedger: browserAdapterRetryReadyAttemptLedger() },
        { cycle: 1, attemptLedger: exhaustedAttemptLedger() },
      ],
    });

    expect(result).toMatchObject({
      playbookAssessmentAvailableIncidentCount: 2,
      playbookAssessmentInvalidIncidentCount: 0,
      playbookExhaustedCount: 1,
      incompletePlaybookCount: 1,
      zeroAttemptBrowserAdapterRetryCount: 1,
      incompletePlaybookNextStageAttemptHistogram: [
        {
          nextStage: "BROWSER_ADAPTER_RETRY",
          attemptCount: 0,
          incidentCount: 1,
        },
      ],
    });
  });

  it("fails every incomplete-derived aggregate closed on invalid current-cycle evidence", () => {
    const result = buildCourseSupportCloseoutPlaybookDecisionBasis({
      incidents: [
        { cycle: 1, attemptLedger: typedAdapterReadyAttemptLedger() },
        { cycle: 1, attemptLedger: { version: 2, events: [] } },
      ],
    });

    expect(result).toMatchObject({
      playbookAssessmentAvailableIncidentCount: 1,
      playbookAssessmentInvalidIncidentCount: 1,
      playbookExhaustedCount: null,
      incompletePlaybookCount: null,
      zeroAttemptBrowserAdapterRetryCount: null,
      incompletePlaybookNextStageAttemptHistogram: null,
    });
  });
});

describe("course-support path planning", () => {
  it("rejects exact and provider-family code scope collisions", () => {
    expect(
      findConflictingResponderPaths(
        [
          "src/lib/tee-times/adapters/cps/normalize.ts",
          "src/lib/automation/course-support-batches.ts",
          "docs/course-support-responder.md",
        ],
        [
          "src/lib/tee-times/adapters/cps/fetch.ts",
          "src/lib/automation/course-support-batches.ts",
        ],
      ),
    ).toEqual([
      "src/lib/automation/course-support-batches.ts",
      "src/lib/tee-times/adapters/cps/normalize.ts",
    ]);
  });

  it("keeps unrelated provider and documentation scopes independent", () => {
    expect(
      findConflictingResponderPaths(
        [
          "src/lib/tee-times/adapters/chronogolf/fetch.ts",
          "docs/course-support-responder.md",
        ],
        ["src/lib/tee-times/adapters/cps/fetch.ts"],
      ),
    ).toEqual([]);
  });

  it("blocks recovery only for matching provider, fingerprint, or code scope", () => {
    const recovering = {
      providerFamilyKey: "CPS",
      failureFingerprint: "cps-timeout",
      summary: { plannedPaths: ["src/lib/tee-times/adapters/cps/fetch.ts"] },
    };
    expect(
      courseSupportRecoveryBatchesConflict(recovering, {
        providerFamilyKey: "CPS",
        failureFingerprint: "different-failure",
        summary: { plannedPaths: [] },
      }),
    ).toBe(true);
    expect(
      courseSupportRecoveryBatchesConflict(recovering, {
        providerFamilyKey: "CHRONOGOLF",
        failureFingerprint: "cps-timeout",
        summary: { plannedPaths: [] },
      }),
    ).toBe(true);
    expect(
      courseSupportRecoveryBatchesConflict(recovering, {
        providerFamilyKey: "CHRONOGOLF",
        failureFingerprint: "chronogolf-schema",
        summary: {
          plannedPaths: ["src/lib/tee-times/adapters/cps/normalize.ts"],
        },
      }),
    ).toBe(true);
    expect(
      courseSupportRecoveryBatchesConflict(recovering, {
        providerFamilyKey: "CHRONOGOLF",
        failureFingerprint: "chronogolf-schema",
        summary: {
          plannedPaths: ["src/lib/tee-times/adapters/chronogolf/fetch.ts"],
        },
      }),
    ).toBe(false);
  });

  it("reopens only an unreleased verifying batch whose original plan was empty", () => {
    expect(
      canAppendCourseSupportBatchPath({
        status: "VERIFYING",
        releaseSha: null,
        plannedPaths: [],
      }),
    ).toBe(true);
    expect(
      canAppendCourseSupportBatchPath({
        status: "VERIFYING",
        releaseSha: "a".repeat(40),
        plannedPaths: [],
      }),
    ).toBe(false);
    expect(
      canAppendCourseSupportBatchPath({
        status: "VERIFYING",
        releaseSha: null,
        plannedPaths: ["src/lib/adapters/teeitup.ts"],
      }),
    ).toBe(false);
  });

  it.each(["CLAIMED", "IMPLEMENTING"] as const)(
    "keeps ordinary %s path planning available",
    (status) => {
      expect(
        canAppendCourseSupportBatchPath({
          status,
          releaseSha: null,
          plannedPaths: [],
        }),
      ).toBe(true);
    },
  );
});

describe("course-support write-conflict retry", () => {
  it("recognizes Prisma serialization and Postgres deadlock failures", () => {
    expect(isRetryableCourseSupportWriteConflict({ code: "P2034" })).toBe(true);
    expect(isRetryableCourseSupportWriteConflict({ code: "40P01" })).toBe(true);
    expect(
      isRetryableCourseSupportWriteConflict(
        new Error("deadlock detected while writing"),
      ),
    ).toBe(true);
    expect(
      isRetryableCourseSupportWriteConflict(new Error("request timed out")),
    ).toBe(false);
  });

  it("retries a bounded number of rolled-back write conflicts", async () => {
    const conflict = Object.assign(new Error("write conflict"), {
      code: "P2034",
    });
    const operation = vi
      .fn<() => Promise<string>>()
      .mockRejectedValueOnce(conflict)
      .mockRejectedValueOnce(conflict)
      .mockResolvedValue("persisted");
    const sleep = vi.fn(async () => undefined);

    await expect(
      withCourseSupportWriteConflictRetry(operation, { sleep }),
    ).resolves.toBe("persisted");
    expect(operation).toHaveBeenCalledTimes(3);
    expect(sleep).toHaveBeenNthCalledWith(1, 25);
    expect(sleep).toHaveBeenNthCalledWith(2, 50);
  });

  it("does not retry an ownership or validation failure", async () => {
    const operation = vi.fn(async () => {
      throw new Error("Responder ownership changed.");
    });
    const sleep = vi.fn(async () => undefined);

    await expect(
      withCourseSupportWriteConflictRetry(operation, { sleep }),
    ).rejects.toThrow("ownership changed");
    expect(operation).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });
});

